        main(()->{check(logs.roll(roll).count==5&&draft().getBoolean("locationTimedOut"),"timeout never silently saves on later fix");call("retryRecordLocation",new Class<?>[]{});check(logs.roll(roll).count==6,"explicit retry saves valid position");noFix();quick();draft().putLong("recordTap",System.currentTimeMillis()-60000);draft().putLong("recordElapsed",SystemClock.elapsedRealtime()-60000);ForegroundLocation.get(activity).onLocationChanged(LocatedRecordInstrumentation.fix());});
        main(()->{check(logs.roll(roll).count==6&&draft()!=null,"old draft never auto attaches current position");long tap=draft().getLong("recordTap");call("retryRecordLocation",new Class<?>[]{});check(logs.roll(roll).count==7&&logs.shots(roll).get(0).tapped==tap,"still-at-scene confirmation preserves original time");layout();call("openRoll",new Class<?>[]{String.class},roll);check(views(root()).stream().anyMatch(v->v instanceof ContactSheet)&&views(root()).stream().noneMatch(v->v instanceof HorizontalScrollView),"detail film strip always visible without five-tile strip");check(views(root()).stream().filter(v->v instanceof TextView&&((TextView)v).getText().toString().equals("拍摄记录")).count()==7,"flat exposure list preserved");layout();});
        main(()->{android.graphics.Bitmap photo=android.graphics.Bitmap.createBitmap(160,160,android.graphics.Bitmap.Config.ARGB_8888);photo.eraseColor(android.graphics.Color.BLUE);String token=UUID.randomUUID().toString();ReferencePhotos.capture(activity,token,photo);photo.recycle();Location meterFix=LocatedRecordInstrumentation.fix();meterFix.setTime(System.currentTimeMillis()-45000);meterFix.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-45000000000L);meterFix.setSpeed(0);tracker("latest",meterFix);set("latest",meterFix);Intent result=new Intent().putExtra("record_meter",true).putExtra("reference_token",token).putExtra("record_tap",System.currentTimeMillis()).putExtra("record_delta",-10).putExtra("record_zone",480).putExtra("aperture","8").putExtra("shutter","1/125").putExtra("meter_iso",400);activity.onActivityResult(23,Activity.RESULT_OK,result);check(logs.roll(roll).count==8&&logs.shots(roll).get(0).lat!=null&&!ReferencePhotos.forShot(logs,logs.shots(roll).get(0).id).isEmpty(),"meter result shares trusted cached save");check(logs.shots(roll).get(0).locationTime==meterFix.getTime(),"meter photo retains cached fix timestamp");call("showRoll",new Class<?>[]{});layout();String latestId=logs.shots(roll).get(0).id;TextView reading=root().findViewWithTag("exposure-summary:"+latestId);ViewGroup compact=root().findViewWithTag("exposure-info:"+latestId);check(compact.getChildCount()==2&&reading.getText().toString().contains("ISO 400"),"meter ISO stays in first line, no third row");check(root().findViewWithTag("exposure-thumb:"+latestId)!=null&&ContactSheet.photos(activity,logs,roll).containsKey(latestId),"meter reference remains in unified film preview and exposure thumbnail");});
